def drive(me, enemy, arena):
    err = bearing_to(enemy.x, enemy.y)
    a = err
    if a > 180: a -= 360
    if a < -180: a += 360
    if abs(a) > 60:
        # turn toward enemy in place
        if a > 0:
            l, r = -0.6, 0.6
        else:
            l, r = 0.6, -0.6
    else:
        l = max(-1.0, 1.0 - a / 45.0)
        r = min(1.0, 1.0 + a / 45.0)
    return (l, r)

def weapons(me, enemy, arena):
    cmds = []
    try:
        sp = me.weapons["front"]
        if sp["health"] > 0 and me.battery_wh > 0:
            cmds.append(spin("front", int(sp["max_rpm"] * 0.95)))
    except Exception:
        pass
    return cmds

